function coloredTag(value){let v=String(value||'Autre'),key=/basket/i.test(v)?'basket':/soccer/i.test(v)?'soccer':/sports? us/i.test(v)?'sports':/tcg/i.test(v)?'tcg':'other';return `<span class="community-tag ${key}">${esc(v)}</span>`}
