function postGroup(x){return x.group||(/Presse/i.test(x.channel)?'Presse':/Site web/i.test(x.channel)?'Web':'RS')}
function channelColor(c){return {'Instagram':'#da4a8b','Facebook':'#3972cb','TikTok':'#16151f','LinkedIn':'#0877b7','Site web':'#6a55bd','Email':'#27a88e','Presse':'#ec862a','Autre':'#777b8c'}[c]||'#777b8c'}
function calendar(kind,cols=[]){let current=calendarDate[kind],year=current.getFullYear(),month=current.getMonth(),mode=calendarMode[kind],first=new Date(year,month,1),offset=(first.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),today=new Date().toISOString().slice(0,10),items=db[kind].filter(x=>(kind!=='posts'||postGroup(x)===commTab)&&JSON.stringify(x).toLowerCase().includes(query.toLowerCase())&&cols.every(([k])=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]));let label=mode==='year'?String(year):first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});let head=`<div class="calendar-tools"><div class="actions"><button class="btn small" data-cal-nav="${kind}:-1">←</button><button class="btn small" data-cal-today="${kind}">Aujourd’hui</button><button class="btn small" data-cal-nav="${kind}:1">→</button><strong style="text-transform:capitalize;margin-left:8px">${esc(label)}</strong></div><div class="actions">${[['week','Semaine'],['month','Mois'],['year','Année']].map(([k,n])=>`<button class="btn small ${mode===k?'dark':''}" data-cal-mode="${kind}:${k}">${n}</button>`).join('')}</div></div>`;let key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let entry=(x,d)=>{if(kind==='posts')return x.date===d;let a=x.start||x.due,b=x.due||x.start;return a&&a<=d&&b>=d};let event=x=>`<button class="calendar-event ${kind==='posts'?'post':''}" style="--event-color:${kind==='posts'?channelColor(x.channel):'#6c55bc'}" data-edit="${kind}:${esc(x.id)}" title="${esc(x.title)} · ${esc(x.channel||x.status||'')}">${esc(x.title)}</button>`;let cells=(m,compact=false)=>{let start=new Date(year,m,1),off=(start.getDay()+6)%7,n=new Date(year,m+1,0).getDate(),count=Math.ceil((off+n)/7)*7;return `<div class="calendar-grid ${compact?'compact':''}">${['L','M','M','J','V','S','D'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${Array.from({length:count},(_,i)=>{let d=new Date(year,m,1-off+i),k=key(d),events=items.filter(x=>entry(x,k));return `<div class="calendar-day ${d.getMonth()!==m?'outside':''} ${k===today?'today':''}"><button class="calendar-date" data-cal-add="${kind}:${k}" title="Ajouter à cette date">${d.getDate()} <span>＋</span></button><div class="calendar-events">${compact?events.length?`<button class="calendar-dot" data-cal-jump="${kind}:${k}" title="${events.length} élément(s)" style="--event-color:${kind==='posts'?channelColor(events[0].channel):'#6c55bc'}">${events.length}</button>`:'':events.map(event).join('')}</div></div>`}).join('')}</div>`};let body;if(mode==='year')body=`<div class="year-grid">${Array.from({length:12},(_,m)=>`<div class="year-month"><h3>${esc(new Date(year,m,1).toLocaleDateString('fr-FR',{month:'long'}))}</h3>${cells(m,true)}</div>`).join('')}</div>`;else if(mode==='month')body=`<div class="calendar-scroll">${cells(month)}</div>`;else{let d=new Date(current);d.setDate(d.getDate()-(d.getDay()+6)%7);body=`<div class="calendar-scroll"><div class="calendar-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${Array.from({length:7},(_,i)=>{let day=new Date(d);day.setDate(d.getDate()+i);let k=key(day);return `<div class="calendar-day"><button class="calendar-date" data-cal-add="${kind}:${k}">${day.getDate()} <span>＋</span></button><div class="calendar-events">${items.filter(x=>entry(x,k)).map(event).join('')}</div></div>`}).join('')}</div></div>`}return `<div class="panel">${head}${body}<p class="sub" style="margin-top:12px">Clique sur une date pour ajouter un élément. En vue annuelle, clique sur le compteur pour ouvrir la semaine correspondante.</p>${kind==='posts'?`<div class="legend">${[...new Set(items.map(x=>x.channel).filter(Boolean))].map(c=>`<span><i style="background:${channelColor(c)}"></i>${esc(c)}</span>`).join('')}</div>`:''}</div>`}

function generic(kind){let item=db[kind],titles={partners:['RÉSEAU','Partenaires','Contacts et relances des partenaires.'],contacts:['RÉSEAU','Contacts & partenaires','Garde le fil des échanges et des relances.'],tasks:['PRODUCTION','Tâches & planning','Suis les responsabilités et ajuste les dates à tout moment.'],posts:['CONTENUS','Communication','Programme tes publications par canal.'],expenses:['RESSOURCES','Déco & budget','Compare les estimations aux dépenses réelles.']},h=titles[kind];let filtered=item.filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));let cols={partners:[['company','Organisation'],['name','Contact'],['zone','Zone'],['community','Communauté'],['status','Statut'],['next','Relance'],['owner','Responsable'],['note','Commentaire']],contacts:[['company','Organisation'],['name','Contact'],['type','Type'],['status','Statut'],['next','Relance'],['owner','Responsable'],['note','Commentaire']],tasks:[['title','Tâche'],['category','Catégorie'],['owner','Responsable'],['due','Échéance'],['status','Statut'],['note','Commentaire']],posts:[['title','Contenu'],['channel','Canal'],['date','Publication'],['owner','Responsable'],['status','Statut'],['note','Commentaire']],expenses:[['title','Élément'],['category','Catégorie'],['quantity','Qté'],['estimated','Prix total'],['status','Statut'],['note','Commentaire']]}[kind];filtered=filtered.filter(x=>cols.every(([k])=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]));let table=`<div class="panel table-wrap">${filtered.length?`<table class="data"><thead><tr>${cols.map(([k,label])=>`<th>${label}<select class="column-filter" data-column="${k}" aria-label="Filtrer ${label}"><option value="">Tous</option>${[...new Set(item.map(x=>String(x[k]??'')).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${columnFilters[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></th>`).join('')}<th></th></tr></thead><tbody>${filtered.map(x=>`<tr data-row-edit="${kind}:${esc(x.id)}">${cols.map(([k])=>`<td>${k==='status'?pill(x[k]):k==='estimated'||k==='actual'?`<span class="money-negative">${euro(x[k])}</span>`:k==='due'||k==='next'||k==='date'?date(x[k]):k==='zone'||k==='community'?coloredTag(k==='zone'?zname(x[k]):x[k]):k==='company'&&x.logoId?`<span class="logo-cell"><img data-blob-id="${esc(x.logoId)}" alt="${esc(x[k]||'Logo partenaire')}"></span>`:esc(x[k]||'—')}</td>`).join('')}<td><button class="linkbtn" data-edit="${kind}:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Aucune donnée','Ajoute un premier élément pour commencer.')}</div>`;let extra='';if(kind==='expenses')extra=`<div class="cards" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><span class="k">Total prévu</span><strong><span class="money-negative">${euro(sum(item,x=>x.estimated))}</span></strong></div></div>`;let tabs=['tasks','posts'].includes(kind)?`<div class="tabs"><button class="${tab[kind]==='list'?'active':''}" data-tab="${kind}:list">Liste</button><button class="${tab[kind]==='calendar'?'active':''}" data-tab="${kind}:calendar">Calendrier</button></div>`:'';return heading(h[0],h[1],h[2],actions(kind))+extra+tabs+(tab[kind]==='calendar'?searchBar()+filterBar(kind,item,cols)+calendar(kind,cols):`<div class="toolbar"><input class="search" id="search" placeholder="Rechercher…" value="${esc(query)}"></div>`+table)}

function addressBook(){let items=db.contacts,cols=[['company','Société'],['last','Nom'],['first','Prénom'],['phone','Téléphone'],['email','Email'],['role','Rôle'],['type','Type'],['typeOther','Précision']];let rows=filterItems(items,cols.map(x=>x[0]));return heading('RÉPERTOIRE','Contacts','Carnet de contacts du salon.',`<button class="btn" data-action="import-contacts">↑ Import CSV</button>${actions('contacts')}`)+searchBar()+`<div class="panel table-wrap">${rows.length?`<table class="data"><thead><tr>${cols.map(([k,l])=>filterHead(items,k,l)).join('')}<th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr data-row-edit="contacts:${esc(x.id)}">${cols.map(([k])=>`<td>${esc(x[k]||'—')}</td>`).join('')}<td><button class="linkbtn" data-edit="contacts:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Carnet vide','Crée un contact ou importe un CSV.')}</div>`}
function invoices(){let items=db.invoices,cols=[['title','Document'],['tag','Type'],['author','Auteur'],['amount','Montant'],['validated','Validé'],['status','Statut'],['note','Commentaire']];let rows=filterItems(items,['title','tag','author','status','note','amount','validated']);return heading('FINANCES','Factures / Devis','Documents, montants et suivi du paiement.',actions('invoices'))+searchBar()+`<div class="panel table-wrap">${rows.length?`<table class="data"><thead><tr><th>Aperçu</th>${cols.map(([k,l])=>filterHead(items,k,l)).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr data-row-edit="invoices:${esc(x.id)}"><td><div class="asset-thumb">${x.mime?.startsWith('image/')?`<img data-blob-id="${esc(x.blobId)}" alt="Aperçu">`:'▤'}</div></td><td><strong>${esc(x.title||x.fileName)}</strong></td><td>${pill(x.tag)}</td><td>${esc(x.author||'—')}</td><td class="money-negative">${euro(x.amount)}</td><td>${x.validated?'✓':'—'}</td><td>${pill(x.status)}</td><td>${esc(x.note||'—')}</td><td><div class="actions"><button class="btn small" data-blob-view="${esc(x.blobId)}" ${x.blobId?"":"disabled"}>Voir</button><button class="btn small" data-blob-download="${esc(x.blobId)}" ${x.blobId?"":"disabled"}>↓</button><button class="btn small" data-edit="invoices:${esc(x.id)}">Ouvrir</button></div></td></tr>`).join('')}</tbody></table>`:empty('Aucune facture ou devis','Ajoute un document.')}</div>`}
function communications(){let all=db.posts.filter(x=>postGroup(x)===commTab),active=filterItems(all.filter(x=>x.status!=='Publié'),['title','company','contact','channel','status','owner','note']),published=filterItems(all.filter(x=>x.status==='Publié'),['title','company','channel','owner']);let tabs=`<div class="tabs">${['RS','Presse','Web'].map(k=>`<button class="${commTab===k?'active':''}" data-comm-tab="${k}">${k}</button>`).join('')}</div>`;let controls=`<div class="tabs"><button class="${tab.posts==='list'?'active':''}" data-tab="posts:list">Liste / cartes</button><button class="${tab.posts==='calendar'?'active':''}" data-tab="posts:calendar">Calendrier</button></div>`;let body=tab.posts==='calendar'?calendar('posts',[['group','Canal']]):commTab==='Web'?`<div class="web-board">${[['Idée|À faire','À faire'],['À créer|En cours','En cours'],['En validation','En validation'],['Planifiée|Terminée','Terminé']].map(([status,title])=>`<div class="panel"><h2>${title}</h2>${active.filter(x=>status.split('|').includes(x.status)).map(x=>`<div class="web-card" data-row-edit="posts:${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${esc(x.owner||'—')}</small></div>`).join('')}</div>`).join('')}</div>`:`<div class="panel table-wrap">${postTable(active)}</div>`;return heading('CONTENUS','Communication','RS, presse et web avec historique des publications.',`<button class="btn primary" data-add="posts">+ Ajouter</button>`)+tabs+controls+searchBar()+filterBar('posts',all,[['status','Statut'],['owner','Responsable'],['channel','Sous-canal'],['company','Entreprise']])+body+`<div class="panel"><div class="panel-head"><h2>Publié</h2><small>${published.length} publication(s)</small></div>${published.length?postTable(published,true):empty('Rien de publié','Les éléments au statut Publié apparaîtront ici.')}</div>`}
function postTable(items,pub=false){return items.length?`<table class="data"><thead><tr><th>Sujet</th><th>Canal</th><th>Entreprise</th><th>Contact</th><th>Responsable</th><th>Statut</th><th>${pub?'Publié le':'Date'}</th><th>Action</th></tr></thead><tbody>${items.map(x=>`<tr data-row-edit="posts:${esc(x.id)}"><td><strong>${esc(x.title)}</strong></td><td>${esc(x.channel||postGroup(x))}</td><td>${esc(x.company||'—')}</td><td>${esc(x.contact||'—')}</td><td>${esc(x.owner||'—')}</td><td>${pill(x.status)}</td><td>${pub?date(x.publishedAt?.slice(0,10)):date(x.date)}</td><td><button class="linkbtn" data-edit="posts:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Aucun élément','Ajoute un contenu ou un contact presse.')}
function settings(){return heading('CONFIGURATION','Réglages','Capacités, tarifs et équipe du CRM.')+`<div class="grid2"><div><div class="panel"><div class="panel-head"><h2>Zones du salon</h2><small>Capacité en tables</small></div><div class="form-grid"><label class="full">Nombre total de tables<input type="number" min="0" data-total-tables value="${db.settings.totalTables}"></label>${db.zones.map((z,i)=>`<label>${esc(z.name)}<input type="number" min="0" data-capacity="${i}" value="${z.capacity}"></label>`).join('')}</div><p class="sub" style="margin-top:14px">Somme des zones : ${sum(db.zones,x=>x.capacity)} · écart : ${db.settings.totalTables-sum(db.zones,x=>x.capacity)}.</p></div><div class="panel"><div class="panel-head"><h2>Responsables potentiels</h2></div><div class="list">${db.settings.owners.map(x=>`<div class="list-item"><strong>${esc(x)}</strong><button class="btn small danger" data-owner-delete="${esc(x)}">Supprimer</button></div>`).join('')}</div><form id="ownerForm" class="actions" style="margin-top:15px"><input class="field" name="owner" required placeholder="Prénom et nom"><button class="btn primary">Ajouter</button></form><p class="sub" style="margin-top:12px">Les responsables restent sur les fiches existantes après leur retrait de cette liste.</p></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>Tarifs partenaires ${editionYear}</h2></div><div class="form-grid"><label>Prix au m² (€)<input type="number" min="0" step="any" data-partner-price="partnerSqmPrice" value="${db.settings.partnerSqmPrice}"></label><label>Prix par table partenaire (€)<input type="number" min="0" step="any" data-partner-price="partnerTablePrice" value="${db.settings.partnerTablePrice}"></label></div></div><div class="panel"><div class="panel-head"><h2>Score des préférences</h2></div><div class="form-grid">${db.settings.score.map((v,i)=>`<label>Choix ${i+1} · points<input type="number" min="0" data-score="${i}" value="${v}"></label>`).join('')}</div></div>`}
function revenueLine(x,f){return x.kind==='Table'?Number(x.quantity||0)*Number(f.partnerTablePrice||0):x.kind==='m²'?Number(x.quantity||0)*Number(f.priceSqm||0):Number(x.amount||0)}
function forecast(){let f=db.forecast2027,rev=Number(f.proTables)*Number(f.proPrice)+Number(f.collectorTables)*Number(f.collectorPrice)+sum(f.extraRevenue,x=>revenueLine(x,f)),cost=Number(f.hallRental)+Number(f.deco)+Number(f.social)+Number(f.press)+sum(f.extraExpense,x=>x.amount),remain=Number(f.totalTables)-Number(f.proTables)-Number(f.collectorTables)-Number(f.partnerTables);let input=(k,l)=>`<label>${l}<input type="number" min="0" step="any" data-forecast="${k}" value="${esc(f[k])}"></label>`;let rows=f.extraRevenue.map(x=>`<div class="forecast-line"><input class="field" placeholder="Recette" data-extra-name="extraRevenue:${esc(x.id)}" value="${esc(x.name)}"><select class="field" data-extra-kind="${esc(x.id)}"><option value="Libre" ${!x.kind||x.kind==='Libre'?'selected':''}>Autre</option><option value="Table" ${x.kind==='Table'?'selected':''}>Partenaire · table</option><option value="m²" ${x.kind==='m²'?'selected':''}>Partenaire · m²</option></select><input class="field" type="number" min="0" step="any" aria-label="Montant ou quantité" data-extra-amount="extraRevenue:${esc(x.id)}" value="${esc(x.kind&&x.kind!=='Libre'?x.quantity??0:x.amount??0)}"><strong class="money-positive">${euro(revenueLine(x,f))}</strong><button class="btn small danger" data-extra-delete="extraRevenue:${esc(x.id)}">✕</button></div>`).join('');let out=f.extraExpense.map(x=>`<div class="forecast-extra"><input class="field" data-extra-name="extraExpense:${esc(x.id)}" value="${esc(x.name)}"><input class="field" type="number" min="0" data-extra-amount="extraExpense:${esc(x.id)}" value="${esc(x.amount)}"><button class="btn small danger" data-extra-delete="extraExpense:${esc(x.id)}">✕</button></div>`).join('');return heading('SIMULATION','Prévisionnel '+(editionYear+1),'Les partenaires sont facturés par table ou par m² selon chaque ligne de recette.')+`<div class="forecast-cards"><div class="stat"><span class="k">Recettes totales</span><strong class="money-positive">${euro(rev)}</strong></div><div class="stat"><span class="k">Dépenses totales</span><strong class="money-negative">${euro(cost)}</strong></div><div class="stat"><span class="k">Résultat</span><strong class="${moneyClass(rev-cost)}">${signedEuro(rev-cost)}</strong></div></div><div class="panel"><h2>Hypothèses de tables</h2><div class="form-grid">${input('totalTables','Nombre total de tables')}${input('proTables','Tables pro')}${input('collectorTables','Tables particulier')}${input('partnerTables','Tables partenaires')}</div><p class="${remain<0?'warning':'sub'}">${remain}/${f.totalTables} tables restantes</p></div><div class="grid2"><div class="panel"><h2>Recettes</h2><div class="form-grid">${input('proPrice','Prix table pro (€)')}${input('collectorPrice','Prix table particulier (€)')}${input('priceSqm','Prix m² (€)')}${input('partnerTablePrice','Prix de la table partenaire (€)')}</div><p class="sub">Tables pro : ${euro(Number(f.proTables)*Number(f.proPrice))} · Particuliers : ${euro(Number(f.collectorTables)*Number(f.collectorPrice))}</p><div class="section">Recettes supplémentaires</div>${rows}<button class="btn small" data-extra-add="extraRevenue">+ Ajouter une recette</button></div><div class="panel"><h2>Dépenses</h2><div class="form-grid">${input('hallRental','Location salle (€)')}${input('deco','Déco (€)')}${input('social','Com réseaux sociaux (€)')}${input('press','Com presse (€)')}</div><div class="section">Autres dépenses</div>${out}<button class="btn small" data-extra-add="extraExpense">+ Ajouter une dépense</button></div></div>`}
function ideas(){let filtered=filterItems(db.ideas,['title','author','price','link','note']);return heading('INSPIRATION','Boîte à idées','Dépose des pistes, des liens et des visuels, puis retrouve-les facilement.',actions('ideas'))+searchBar()+filterBar('ideas',db.ideas,[['title','Idée'],['author','Auteur'],['price','Prix'],['link','Lien'],['note','Commentaire']])+`<div class="idea-grid">${filtered.length?filtered.map(x=>`<article class="idea-card"><div class="idea-image">${x.imageId?`<img data-blob-id="${esc(x.imageId)}" alt="Visuel de l’idée">`:'✦'}</div><div class="idea-body"><div class="actions" style="justify-content:space-between"><span class="pill">${esc(x.author||'Sans auteur')}</span><span class="idea-price">Montant estimé <strong class="money-negative">${euro(x.price)}</strong></span></div><h2>${esc(x.title||'Sans titre')}</h2><p>${esc(x.note||'Aucun commentaire')}</p>${x.link?`<a href="${safeUrl(x.link)}" target="_blank" rel="noopener noreferrer">Voir le lien ↗</a>`:''}<div class="actions" style="margin-top:15px"><button class="btn small" data-edit="ideas:${esc(x.id)}">Modifier</button><button class="btn small danger" data-delete="ideas:${esc(x.id)}">Supprimer</button></div></div></article>`).join(''):empty('Aucune idée','Ajoute ta première idée.')}</div>`}
function assets(){let filtered=filterItems(db.assets,['title','category','author','fileName','note']);return heading('DOCUMENTS','Assets','Tous les documents à consulter et télécharger depuis cet appareil.',actions('assets'))+searchBar()+filterBar('assets',db.assets,[['title','Document'],['category','Catégorie'],['author','Auteur'],['fileName','Fichier'],['note','Commentaire']])+`<div class="panel table-wrap">${filtered.length?`<table class="data"><thead><tr><th>Aperçu</th>${[['title','Document'],['category','Catégorie'],['author','Auteur'],['fileName','Fichier'],['note','Commentaire']].map(([k,l])=>filterHead(db.assets,k,l)).join('')}<th>Actions</th></tr></thead><tbody>${filtered.map(x=>`<tr data-row-edit="assets:${esc(x.id)}"><td><div class="asset-thumb">${x.blobId&&x.mime?.startsWith('image/')?`<img data-blob-id="${esc(x.blobId)}" alt="Aperçu">`:'▤'}</div></td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.category||'—')}</td><td>${esc(x.author||'—')}</td><td>${esc(x.fileName||'—')}</td><td>${esc(x.note||'—')}</td><td><div class="actions"><button class="btn small" data-blob-view="${esc(x.blobId||'')}">Voir</button><button class="btn small" data-blob-download="${esc(x.blobId||'')}">↓</button><button class="btn small" data-edit="assets:${esc(x.id)}">Modifier</button><button class="btn small danger" data-delete="assets:${esc(x.id)}">✕</button></div></td></tr>`).join('')}</tbody></table>`:empty('Aucun asset','Ajoute un fichier pour le consulter ici.')}</div><div class="note">Les fichiers sont privés et partagés avec les membres autorisés du salon.</div>`}
function safeUrl(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch(e){return '#'}}
function searchBar(){return `<div class="toolbar"><input class="search" id="search" placeholder="Rechercher…" value="${esc(query)}"></div>`}
function filterItems(items,keys){return items.filter(x=>JSON.stringify(keys.map(k=>x[k])).toLowerCase().includes(query.toLowerCase())&&keys.every(k=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]))}
function filterHead(items,k,label){return `<th>${label}<select class="column-filter" data-column="${k}" aria-label="Filtrer ${label}"><option value="">Tous</option>${[...new Set(items.map(x=>String(x[k]??'')).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${columnFilters[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></th>`}
function filterBar(kind,items,cols){return `<div class="toolbar">${cols.map(([k,label])=>`<label class="filter-label">${label}<select class="field" data-column="${k}"><option value="">Tous</option>${[...new Set(items.map(x=>String(x[k]??'')).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${columnFilters[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div>`}

function render(){applyTheme();nav();document.getElementById('content').innerHTML=({dashboard,exhibitors,partners:()=>generic('partners'),contacts:addressBook,tasks:()=>generic('tasks'),posts:communications,expenses:()=>generic('expenses'),ideas,assets,invoices,forecast,settings})[view]()+`<p class="footer">Lille Card Show · V1 en ligne · Dernière modification ${db.updatedAt?new Date(db.updatedAt).toLocaleString('fr-FR'):'aucune'}</p>`;hydrateBlobs()}function go(v){view=v;if(v==='exhibitors')exhibitorTab='exhibitors';query='';columnFilters={};selectedExhibitors.clear();zoneFilter='';statusFilter='';render();scrollTo(0,0)}
