function edit(kind,key,preset){let obj=key?db[kind].find(x=>x.id===key):null;let old=obj||preset||{};if(kind==='exhibitors'&&!obj)old.vendorType='À définir';if(kind==='exhibitors'&&obj){let [first,last]=nameParts(obj);old={...obj,first,last}}if(kind==='posts'&&!obj)old={...old,group:commTab,status:commTab==='Presse'?'À contacter':'Idée'};if(kind==='posts')old={...old,group:postGroup(old)};let info=kind==='exhibitors'&&obj&&obj.source?`<div class="note">Source : HelloAsso · commande ${esc(obj.order||'—')} · billet ${esc(obj.ticket||'—')}. Un nouvel import actualise les données source et conserve tes choix, attribution et commentaires.</div>`:'';let comments=obj?.comments||[];modal(`${obj?'Modifier':'Ajouter'} ${kind==='exhibitors'?'un exposant':cfg[kind].label.toLowerCase()}`,`${info}<form id="editForm" data-kind="${kind}" data-id="${esc(key||'')}"><div class="form-grid" style="margin-top:16px">${fields(kind,old)}${['partners','ideas','assets','invoices'].includes(kind)?`<label class="full">${['assets','invoices'].includes(kind)?'Fichier':kind==='partners'?'Logo (partenaire)':'Image'}<input name="upload" type="file" ${['assets','invoices'].includes(kind)?'':'accept="image/*"'}></label>`:''}</div><div class="modal-actions">${obj?`<button type="button" class="btn danger" data-delete="${kind}:${esc(key)}">Supprimer</button>`:''}<button class="btn primary">Enregistrer</button></div></form>${obj&&(['partners','ideas'].includes(kind))&&obj[kind==='partners'?'logoId':'imageId']?`<p class="sub">Image actuelle conservée si aucun nouveau fichier n’est choisi.</p>`:''}${extraEditor(kind,obj||old)}${kind==='tasks'&&obj?`<div class="section">Commentaires (${comments.length})</div>${comments.map(c=>`<div class="comment">${esc(c.text)}<small>${esc(c.author)} · ${date(c.date)}</small></div>`).join('')}<form id="commentForm" data-id="${esc(key)}" class="form-grid"><label>Ton nom<input name="author" placeholder="Prénom" required></label><label class="full">Commentaire<textarea name="text" required placeholder="Ajouter une précision, un suivi…"></textarea></label><button class="btn dark" style="width:max-content">Ajouter le commentaire</button></form>`:''}`);syncPostFields()}
function download(name,data,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}function csvParse(s,sep){if(s.charCodeAt(0)===65279)s=s.slice(1);let rows=[],row=[],cell='',quoted=false;for(let i=0;i<s.length;i++){let c=s[i];if(quoted){if(c==='"'&&s[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===sep){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v!==''))rows.push(row);return rows}function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}function detect(headers,fragments){return headers.findIndex(h=>fragments.some(f=>norm(h)===norm(f))) }let importRows=[],importHeaders=[],importName='';function importModal(){modal('Importer un CSV HelloAsso',`<p class="sub">L’import repère les billets de table et ignore les repas et autres produits. Les lignes retenues seront enregistrées dans l’espace partagé du salon.</p><div class="form-grid" style="margin:18px 0"><label class="full">Choisir le CSV<input id="csvFile" type="file" accept=".csv,text/csv"></label></div><div id="csvPreview"></div>`)}function parseImport(text,name){let first=text.split(/\r?\n/)[0],sep=(first.match(/;/g)||[]).length>=(first.match(/,/g)||[]).length?';':',';let rows=csvParse(text,sep);importHeaders=rows.shift()||[];importRows=rows;importName=name;let h=importHeaders;let mapping={order:detect(h,['Référence commande','Référence de commande']),ticket:detect(h,['Numéro de billet','Identifiant billet']),last:detect(h,['Nom participant','Nom']),first:detect(h,['Prénom participant','Prénom']),company:detect(h,['Raison sociale','Société']),email:detect(h,['adresse eMail','Email participant','Email payeur']),rate:detect(h,['Tarif','Formule']),amount:detect(h,['Montant tarif','Montant du tarif']),community:detect(h,['Quel sport ? Quelle communauté (Pokemon, Magic, Yugi-Oh! ...)','Sport','Communauté']),status:detect(h,['Statut de la commande','Statut'])};let labels={order:'Référence commande',ticket:'Numéro de billet',last:'Nom participant',first:'Prénom participant',company:'Raison sociale',email:'Email',rate:'Tarif / formule',amount:'Montant tarif (€)',community:'Sport / communauté',status:'Statut commande'};document.getElementById('csvPreview').innerHTML=`<div class="note">${esc(name)} · ${rows.length} lignes détectées. Vérifie la correspondance des colonnes avant d’importer.</div><div class="form-grid" style="margin:15px 0">${Object.entries(labels).map(([k,v])=>`<label>${v}<select data-map="${k}"><option value="-1">— Non présent —</option>${h.map((x,i)=>`<option value="${i}" ${mapping[k]===i?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`).join('')}</div><label style="font-size:12px"><input type="checkbox" id="tableOnly" checked> Importer seulement les billets dont le tarif contient « table » ou « partenaire »</label><p class="sub" style="margin:12px 0">Exemple : ${esc(rows.slice(0,4).map(r=>r[mapping.rate]||'').join(' · '))}</p><button class="btn primary" data-action="commit-csv">Importer les fiches</button>`}function parseMoney(v){let s=String(v||'').replace(/[^\d,.-]/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');return Math.max(0,Number(s)||0)}function normalizeCommunity(v){let x=norm(v);return /tcg|pokemon|one piece|magic|yugi|lorcana/.test(x)?'TCG':/basket|nba|bball/.test(x)?'Basket':/nfl|mlb|baseball|hockey|sport us|foot us|football americain/.test(x)?'Sport US':/soccer|football|foot/.test(x)?'Soccer':'Autre'}function vendorFromRate(rate){let v=norm(rate);return /partenaire|partner|sponsor/.test(v)?'Partenaire':/collectionneur|particulier/.test(v)?'Collectionneur':/\bpro\b|professionnel/.test(v)?'Pro':'À définir'}function commitImport(){let m={};document.querySelectorAll('[data-map]').forEach(e=>m[e.dataset.map]=Number(e.value));if(m.rate<0){alert('Associe au moins la colonne Tarif pour distinguer les exposants des autres billets.');return}let get=(r,k)=>m[k]>=0?(r[m[k]]||'').trim():'';let created=0,updated=0,skipped=0;for(let r of importRows){let rate=get(r,'rate');if(document.getElementById('tableOnly').checked&&!/table|partenaire|partner|sponsor/i.test(rate)){skipped++;continue}let ticket=get(r,'ticket'),order=get(r,'order');let sourceKey=ticket?'ticket:'+ticket:order?'order:'+order+'|'+norm(get(r,'first')+' '+get(r,'last'))+'|'+norm(rate):'';if(!sourceKey){skipped++;continue}let ex=db.exhibitors.find(x=>x.sourceKey===sourceKey),isNew=!ex;if(!ex){ex={id:id(),tables:1,amount:0,vendorType:'À définir',status:'À traiter',choice1:'',choice2:'',choice3:'',zone:'',note:'',comments:[]};db.exhibitors.push(ex)}ex.source='HelloAsso';ex.sourceKey=sourceKey;ex.order=order;ex.ticket=ticket;ex.first=get(r,'first')||ex.first||'';ex.last=get(r,'last')||ex.last||'';ex.name=[ex.first,ex.last].filter(Boolean).join(' ')||ex.name||'';ex.company=get(r,'company')||ex.company||'';ex.email=get(r,'email')||ex.email||'';ex.rate=rate;if(isNew){ex.vendorType=vendorFromRate(rate);ex.amount=parseMoney(get(r,'amount'))}else{if(!ex.amountEdited)ex.amount=parseMoney(get(r,'amount'));if(!ex.vendorEdited)ex.vendorType=vendorFromRate(rate)}ex.rawCommunity=get(r,'community')||ex.rawCommunity||'';if(isNew||!ex.communityEdited)ex.community=normalizeCommunity(ex.rawCommunity);ex.sourceStatus=get(r,'status');if(isNew&&/annul|rembours/i.test(ex.sourceStatus))ex.status='Annulé';isNew?created++:updated++}save();close();render();notify(`${created} créés · ${updated} mis à jour · ${skipped} ignorés`)}
