function contactCSV(text){let first=text.split(/\r?\n/)[0],sep=(first.match(/;/g)||[]).length>=(first.match(/,/g)||[]).length?';':',',rows=csvParse(text,sep),head=rows.shift()||[],mapping={company:['société','societe','organisation','entreprise'],last:['nom','nom de famille'],first:['prénom','prenom'],phone:['téléphone','telephone','tel','portable'],email:['email','e-mail','mail'],role:['rôle','role','fonction'],type:['type','catégorie','categorie']};let idx=Object.fromEntries(Object.entries(mapping).map(([k,n])=>[k,detect(head,n)])),created=0,updated=0;for(let row of rows){let val=k=>idx[k]<0?'':String(row[idx[k]]||'').trim(),email=val('email'),last=val('last');if(!email&&!last&&!val('company'))continue;let old=db.contacts.find(x=>email&&norm(x.email)===norm(email))||db.contacts.find(x=>!email&&x.company===val('company')&&x.last===last&&x.first===val('first'));let obj=old||{id:id()};for(let k of Object.keys(mapping))if(val(k))obj[k]=val(k);if(!old){db.contacts.push(obj);created++}else updated++}save();close();render();notify(created+' contacts ajoutés · '+updated+' actualisés')}
